import time

attempts = {"count": 0}

def call_api():
    attempts["count"] += 1
    if attempts["count"] < 3:
        raise RuntimeError("429 Too Many Requests")
    return "你好，我是 Agent"

def call_with_retry(max_attempts=3, base_delay=1):
    for attempt in range(max_attempts):
        try:
            return call_api()
        except RuntimeError:
            if attempt == max_attempts - 1:
                raise
            time.sleep(base_delay * (2 ** attempt))

print(call_with_retry())
print(f"attempts={attempts['count']}")

