import re
import sqlite3

conn = sqlite3.connect("orders.db")
conn.execute("DROP TABLE IF EXISTS orders")
conn.execute("CREATE TABLE orders (id TEXT PRIMARY KEY, date TEXT NOT NULL)")
conn.executemany(
    "INSERT INTO orders (id, date) VALUES (?, ?)",
    [("A001", "2026-11-03"), ("A002", "2026-11-03"), ("A003", "2026-11-04")],
)
conn.commit()
conn.close()

def query_orders(date):
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
        return {"ok": False, "error": "日期格式应为 YYYY-MM-DD"}

    conn = sqlite3.connect("orders.db")
    try:
        rows = conn.execute(
            "SELECT id FROM orders WHERE date = ?", (date,)
        ).fetchall()
    except sqlite3.Error:
        return {"ok": False, "error": "数据库暂时不可用，请稍后重试"}
    finally:
        conn.close()

    if not rows:
        return {"ok": False, "error": "该日期没有订单"}
    return {"ok": True, "result": [row[0] for row in rows]}

print(query_orders("2026-11-03"))
print(query_orders("2026/11/03"))
print(query_orders("2026-11-05"))

