DOCS = [
    {"id": "refund", "title": "退款政策", "text": "七天无理由退款，退款原路返回，一般 1-3 个工作日到账。"},
    {"id": "invoice", "title": "发票说明", "text": "订单完成后可在订单详情申请电子发票。"},
    {"id": "shipping", "title": "配送说明", "text": "默认顺丰发货，偏远地区可能延迟。"},
]

def chunk_text(text, size=12):
    return [text[i:i + size] for i in range(0, len(text), size)]

def search(query, top_k=2):
    hits = []
    for doc in DOCS:
        for index, chunk in enumerate(chunk_text(doc["text"])):
            score = chunk.count(query)
            if score:
                hits.append({
                    "id": f"{doc['id']}#{index}",
                    "text": chunk,
                    "score": score,
                })
    hits.sort(key=lambda item: item["score"], reverse=True)
    return hits[:top_k]

for item in search("退款"):
    print(item["id"], item["text"])

