BUDGET = 0.05
COST_PER_CALL = 0.02
cache = {}
spent = {"total": 0.0}

def call_llm(question):
    if question in cache:
        return f"缓存：{cache[question]}"
    if spent["total"] + COST_PER_CALL > BUDGET:
        return "预算不足，已降级"
    spent["total"] += COST_PER_CALL
    answer = f"回答：{question}"
    cache[question] = answer
    return answer

questions = ["退款多久到账", "退款多久到账", "发票怎么开", "发票怎么开"]
