def assign_role(task):
    if any(key in task for key in ("校对", "检查")):
        return "reviewer"
    if any(key in task for key in ("搜索", "资料", "查")):
        return "researcher"
    if any(key in task for key in ("写", "文案", "总结")):
        return "writer"
    return "generalist"

n = int(input())
tasks = [input().strip() for _ in range(n)]
counts = {"researcher": 0, "writer": 0, "reviewer": 0, "generalist": 0}
for task in tasks:
    role = assign_role(task)
    counts[role] += 1
    print(f"{task}: {role}")
print(" ".join(f"{role}={counts[role]}" for role in ("researcher", "writer", "reviewer", "generalist")))
